import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: true,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
  };

  const slides = [
    {
      id: 1,
      title: "Slide 1",
      image: "https://via.placeholder.com/1024x394?text=Slide+1",
    },
    {
      id: 2,
      title: "Slide 2",
      image: "https://via.placeholder.com/1024x394?text=Slide+2",
    },
    {
      id: 3,
      title: "Slide 3",
      image: "https://via.placeholder.com/1024x394?text=Slide+3",
    },
  ];

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        maxWidth: "1024px",
        margin: "0 auto",
        border: "15px solid #00C26D",
        borderRadius: "10px",
        overflow: "hidden",
        backgroundColor: "#293349",
      }}
    >
      {/* Kesik Çizgiler */}
      <div
        style={{
          position: "absolute",
          top: "0",
          left: "0",
          display: "flex",
          flexDirection: "column",
          gap: "5px",
          padding: "10px",
        }}
      >
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#293349",
          }}
        ></div>
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#293349",
          }}
        ></div>
        <div
          style={{
            width: "5px",
            height: "5px",
            borderRadius: "50%",
            backgroundColor: "#293349",
          }}
        ></div>
      </div>
      <div
        style={{
          position: "absolute",
          top: "0",
          right: "0",
          display: "flex",
          flexDirection: "row",
          gap: "5px",
          padding: "10px",
        }}
      >
        <div
          style={{
            width: "10px",
            height: "2px",
            backgroundColor: "#293349",
            transform: "rotate(45deg)",
          }}
        ></div>
        <div
          style={{
            width: "10px",
            height: "2px",
            backgroundColor: "#293349",
            transform: "rotate(45deg)",
          }}
        ></div>
        <div
          style={{
            width: "10px",
            height: "2px",
            backgroundColor: "#293349",
            transform: "rotate(45deg)",
          }}
        ></div>
      </div>

      {/* Slider */}
      <Slider {...settings}>
        {slides.map((slide) => (
          <div key={slide.id}>
            <div
              style={{
                height: "394px",
                backgroundImage: `url(${slide.image})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
                position: "relative",
              }}
            >
              <h2
                style={{
                  color: "#fff",
                  textAlign: "center",
                  position: "absolute",
                  bottom: "20px",
                  width: "100%",
                  fontSize: "24px",
                }}
              >
                {slide.title}
              </h2>
            </div>
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default EventsSlider;
